#!/bin/bash

# 1. Register new activity in AndroidManifest
sed -i 's|</application>|    <activity android:name=".SmartReaderActivity" android:exported="false"/>\n    </application>|g' app/src/main/AndroidManifest.xml

# 2. Add Smart Reader & Settings Hub to More Tab XML safely
sed -i 's/android:id="@+id\/btnContactUs"[^>]*\/>/&\n\n    <!-- Smart Reader Launcher -->\n    <TextView android:text="Smart Tools" android:textColor="#B0BEC5" android:layout_width="wrap_content" android:layout_height="wrap_content" android:textStyle="bold" android:textSize="14sp" android:layout_marginTop="24dp"\/>\n    <Button android:id="@+id\/btnOpenSmartReader" android:text="OPEN SMART DOCUMENT READER" android:layout_width="match_parent" android:layout_height="wrap_content" android:layout_marginTop="8dp" android:backgroundTint="#03DAC5" android:textColor="#000000"\/>\n\n    <!-- Settings Hub -->\n    <TextView android:text="Settings Hub" android:textColor="#B0BEC5" android:layout_width="wrap_content" android:layout_height="wrap_content" android:textStyle="bold" android:textSize="14sp" android:layout_marginTop="24dp"\/>\n    <Button android:id="@+id\/btnSettingsTimerBattery" android:text="TIMER, BATTERY \&amp; AUDIO SETTINGS" android:layout_width="match_parent" android:layout_height="wrap_content" android:layout_marginTop="8dp"\/>\n    <Button android:id="@+id\/btnSettingsDisplay" android:text="DISPLAY SETTINGS" android:layout_width="match_parent" android:layout_height="wrap_content" android:layout_marginTop="8dp"\/>\n    <Button android:id="@+id\/btnSettingsSmartReader" android:text="SMART READER SETTINGS" android:layout_width="match_parent" android:layout_height="wrap_content" android:layout_marginTop="8dp"\/>\n    <Button android:id="@+id\/btnSettingsSound" android:text="SOUND \&amp; VIBRATION" android:layout_width="match_parent" android:layout_height="wrap_content" android:layout_marginTop="8dp"\/>/g' app/src/main/res/layout/activity_main.xml

# 3. Add click logic to MainActivity
sed -i 's/setupButtonClick("btnPreviewCall"/setupButtonClick("btnOpenSmartReader", v -> startActivity(new Intent(MainActivity.this, SmartReaderActivity.class)));\n        setupButtonClick("btnSettingsTimerBattery", v -> Toast.makeText(this, "Timer \\& Battery Settings coming soon...", Toast.LENGTH_SHORT).show());\n        setupButtonClick("btnSettingsDisplay", v -> Toast.makeText(this, "Display Settings coming soon...", Toast.LENGTH_SHORT).show());\n        setupButtonClick("btnSettingsSmartReader", v -> Toast.makeText(this, "Smart Reader Settings coming soon...", Toast.LENGTH_SHORT).show());\n        setupButtonClick("btnSettingsSound", v -> Toast.makeText(this, "Sound \\& Vibration Settings coming soon...", Toast.LENGTH_SHORT).show());\n\n        &/g' app/src/main/java/com/speechplus/tts/MainActivity.java

